package main

import (
	"context"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"time"
)

type User struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

func main() {
	// Create a context with a 5-second timeout
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()

	req, err := http.NewRequestWithContext(ctx, "GET", "https://jsonplaceholder.typicode.com/users/1", nil)
	if err != nil {
		log.Fatalf("Error creating request: %v", err)
	}

	client := &http.Client{}
	resp, err := client.Do(req)
	if err != nil {
		log.Fatalf("Error making request: %v", err)
	}
	defer resp.Body.Close()

	var user User
	if err := json.NewDecoder(resp.Body).Decode(&user); err != nil {
		log.Fatalf("Error decoding JSON: %v", err)
	}

	fmt.Printf("User: %s (%s)\n", user.Name, user.Email)
}

#include <iostream>
#include <fstream>
#include <string>

int main() {
    // Open the file using RAII
    std::ifstream file("data.txt");

    // Check if the file successfully opened
    if (!file.is_open()) {
        std::cerr << "Error: Could not open data.txt" << std::endl;
        return 1;
    }

    std::string line;
    int line_number = 1;

    // Read line by line until end-of-file
    while (std::getline(file, line)) {
        std::cout << line_number++ << ": " << line << '\n';
    }

    // No need to call file.close(), RAII handles it automatically!
    return 0;
}
